import {ask} from './confirm.mjs';
import {tools,emptyValues,validateValues,validateProcesses,launchPackages} from './tool-schema.mjs';
import {NEW_KEY,CRM_KEY,OLD_KEY,groups,category,n,leadScore,savings,opportunity,audit,crmStats,parseCRM,mergeLeads,csv,makeRepository,parseDraft,applyTransfer} from './tool-logic.mjs';
import {calculators,defaults} from './calculators.mjs';
export {groups,category};
export const extraTools=tools;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>v===null?'Not attainable':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(v);
const number=v=>v===null?'Unknown':new Intl.NumberFormat('en-US',{maximumFractionDigits:1}).format(v);
const para=s=>esc(s||'Not supplied').replaceAll('\n','<br>');
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
let memory={version:1,drafts:{},processes:[],links:{}},storageWarning='',crmWarning='';
try{const raw=localStorage.getItem(NEW_KEY);if(raw){const d=JSON.parse(raw);if(d.version!==1||!d.drafts||typeof d.drafts!=='object'||!Array.isArray(d.processes)||d.processes.length>100)throw Error();for(const t of tools)if(d.drafts[t.id])memory.drafts[t.id]=validateValues(t,d.drafts[t.id]);memory.processes=validateProcesses(d.processes);memory.links=d.links&&typeof d.links==='object'?Object.fromEntries(Object.entries(d.links).filter(([k,v])=>tools.some(t=>t.id===k)&&typeof v==='string')):{};}}catch{storageWarning='Some saved tool data is malformed or from an unsupported version. It has not been overwritten; export the raw backup before explicitly saving or clearing.'}
const repo=makeRepository({getItem:k=>localStorage.getItem(k),setItem:(k,v)=>localStorage.setItem(k,v),removeItem:k=>localStorage.removeItem(k)});
let leads=[];try{leads=repo.load()}catch{crmWarning='Saved CRM records could not be validated. They have not been overwritten. Export a raw backup before importing a valid replacement.'}
let current,values,result,editId=null,processId=null,search='',stageFilter='',archived=false,saveTimer;
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',4000)}
function saveMemory(explicit=false){if(storageWarning&&!explicit){toast('Saved data needs recovery. Use Export raw backup before saving.');return false}try{localStorage.setItem(NEW_KEY,JSON.stringify(memory));storageWarning='';return true}catch{toast('Storage unavailable or full. Export your work before leaving this page.');return false}}
function saveDraft(explicit=false){try{memory.drafts[current.id]=validateValues(current,values);return saveMemory(explicit)}catch(e){if(explicit)toast('Draft not saved: '+e.message);return false}}
function download(name,data,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000)}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied')}catch{const area=document.createElement('textarea');area.className='copy-fallback';area.setAttribute('aria-label','Select and copy report text');area.value=text;document.querySelector('#app').append(area);area.select();toast('Clipboard unavailable. Select and copy the text below.')}}
const list=items=>items.length?'<ul>'+items.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':'<p>Insufficient evidence supplied.</p>';
const section=(title,text)=>`<section class="report-section"><h3>${esc(title)}</h3><p>${para(text)}</p></section>`;
const metric=(name,value)=>`<div class="metric"><span>${esc(name)}</span><strong>${esc(value)}</strong></div>`;
const scores=r=>`<p class="status-line">${r.score===null?'Unscored':number(r.score)+' / 100'} · ${r.provisional?'Provisional':'All scoring criteria answered'} · ${number(r.coverage)}% weighted coverage</p><table><thead><tr><th>Criterion</th><th>Rating</th><th>Weight</th><th>Points</th></tr></thead><tbody>${r.breakdown.map(b=>`<tr><td>${esc(b.label)}</td><td>${number(b.value)}</td><td>${b.weight}%</td><td>${number(b.points)}</td></tr>`).join('')}</tbody></table>`;
function snapshotText(c,v){return `${c.name} — estimate, not a guarantee.\nInputs: ${c.fields.map(f=>`${f.label}: ${v[f.key]} ${f.unit}`).join('; ')}\nResults: ${c.calculate(v).map(([k,n,u])=>`${k}: ${n===null?'Not attainable':u==='$'?money(n):number(n)+' '+(u??'')}`).join('; ')}\nAssumptions: ${c.formula}\nCalculator defaults may be fictional; verify every input.`}
async function transfer(id,patch,explanation='',leadId){clearTimeout(saveTimer);const tool=tools.find(t=>t.id===id);if(tool&&storageWarning){toast('Recover the saved tool data or explicitly save a draft before transferring.');return false}const old=tool?(memory.drafts[id]??emptyValues(tool)):readOriginal(id);const text=Object.entries(patch).map(([k,v])=>`${tool?.fields.find(f=>f.key===k)?.label??calculators.find(c=>c.id===id)?.fields.find(f=>f.key===k)?.label??k}: ${String(old[k]??'(empty)').slice(0,90)} → ${String(v).slice(0,300)}`).join('\n');if(!await ask(`Transfer to ${tool?.name??calculators.find(c=>c.id===id)?.name}?\n${explanation}\nOnly these fields will change:\n${text}`))return false;
try{if(tool){memory.drafts[id]=validateValues(tool,applyTransfer(old,patch));if(leadId)memory.links[id]=leadId;if(!saveMemory(true))return false}else{const raw=localStorage.getItem(OLD_KEY);const store=raw?JSON.parse(raw):{};if(!store||typeof store!=='object'||Array.isArray(store))throw Error('Original calculator storage is malformed; no transfer made.');store[id]=applyTransfer(old,patch);localStorage.setItem(OLD_KEY,JSON.stringify(store));}location.hash=id;if(current?.id===id)mountExtended(id);toast('Transfer saved. Review the destination assumptions.');return true}catch(e){toast(e.message);return false}}
function readOriginal(id){const c=calculators.find(c=>c.id===id),raw=localStorage.getItem(OLD_KEY);const d=raw?JSON.parse(raw):{};return {...defaults(c),...d?.[id]}}
export function calculatorIntegration(c,v,host){const button=document.createElement('button');button.className='transfer-button';button.textContent=c.id==='launch'?'Create proposal from launch package':'Use assumptions in proposal';button.onclick=async()=>{try{const p=memory.drafts.proposal??emptyValues(tools.find(t=>t.id==='proposal'));const patch={assumptions:(p.assumptions?p.assumptions+'\n\n':'')+snapshotText(c,v)};if(c.id==='launch'){patch.template='Business Launch Concierge';patch.fee=v.p;patch.service=launchPackages.find(x=>x[1]===v.p)?.[0]??'Launch Concierge Standard'}transfer('proposal',patch,'This imports an estimate, including potentially fictional defaults. No client achievements are inferred.')}catch(e){toast(e.message)}};host.append(button)}
function field(f){const value=values[f.key]??'';let html=f.type==='textarea'?`<textarea data-field="${f.key}" maxlength="20000">${esc(value)}</textarea>`:f.type==='select'?`<select data-field="${f.key}"><option value="">Unknown / choose</option>${f.options.map(o=>`<option ${value===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`:`<input data-field="${f.key}" type="${f.type}" ${f.type==='number'?`step="any" min="${f.min}" ${f.max===undefined?'':`max="${f.max}"`}`:'maxlength="20000"'} value="${esc(value)}">`;return `<label class="${f.type==='textarea'?'wide':''}">${esc(f.label)}${html}</label>`}
function form(t){const groups=[...new Set(t.fields.map(f=>f.group))];return groups.map((g,i)=>`<details class="form-group" ${i<2||g==='Assessment ratings'?'open':''}><summary>${esc(g)}</summary><div class="fields">${t.fields.filter(f=>f.group===g).map(field).join('')}</div></details>`).join('')}
const privacy='Local CRM Mode: Data is stored in this browser only. This is not secure cloud storage. Avoid confidential client information and export backups regularly.';
export function mountExtended(id){clearTimeout(saveTimer);current=tools.find(t=>t.id===id);if(!current)return false;values={...emptyValues(current),...memory.drafts[id]};editId=id==='crm'&&leads.some(l=>l.id===memory.links.crm)?memory.links.crm:null;processId=null;if(id==='crm'&&!values.added)values.added=today();const app=document.querySelector('#app');app.innerHTML=`<a class="back" href="#">← All tools</a><div class="eyebrow">${esc(current.category)}</div><div class="calc-head"><div><h1>${current.name}</h1><p>${current.description}</p></div><div class="actions"><button id="new-reset">Reset ${id==='crm'?'form':'template'}</button><button id="new-copy">Copy ${id==='proposal'?'proposal':'results'}</button></div></div><aside class="note local-notice"><p><b>${privacy}</b><br>Records exist only in this browser profile, do not sync between devices, and may be permanently lost when browser data is cleared. No automatic transmission or backup.</p></aside>${storageWarning||crmWarning?`<p class="error" role="alert">${esc(storageWarning+' '+crmWarning)}</p><button id="raw-backup">Export raw recovery backup</button>`:''}<div class="tool-controls"><button id="save-draft">Save draft locally</button><button id="export-json">Export ${id==='crm'?'directory':'draft'} JSON</button><label class="file-control">Import ${id==='crm'?'directory':'draft'} JSON<input id="import-json" type="file" accept=".json,application/json"></label>${['audit','proposal'].includes(id)?'<button id="print-report">Print / Save PDF</button>':''}${id==='crm'?'<button id="csv-export">Export CSV</button><button id="clear-crm">Clear CRM records</button>':''}</div>${id==='proposal'?`<div class="tool-controls"><label>Import saved calculator assumptions<select id="import-calculator"><option value="">Choose calculator</option>${calculators.map(c=>`<option value="${c.id}">${c.name}</option>`).join('')}</select></label><button id="import-calc">Import with confirmation</button><button id="apply-offer">Apply editable service preset</button></div>`:''}${id==='crm'?'<section id="crm-directory" class="panel"></section>':`<div class="tool-controls"><label>Linked local CRM record<select id="lead-link"><option value="">No linked record</option>${leads.map(l=>`<option value="${esc(l.id)}" ${memory.links[id]===l.id?'selected':''}>${esc(l.business||l.contact)}${l.archived?' (archived)':''}</option>`).join('')}</select></label><button id="use-lead">Import lead context</button>${id==='scoring'?'<button id="write-score">Save score to linked lead</button>':''}</div>`}<div class="calculator extended-layout"><section class="panel editor"><h2>${id==='crm'?'Add or edit lead':'Inputs & evidence'}</h2>${form(current)}<p id="tool-error" class="error" role="status"></p>${id==='crm'?'<button id="save-lead">Save lead</button>':''}${id==='opportunities'?'<button id="save-process">Save process to ranking</button>':''}<p class="formula">${esc(current.explanation)}</p><p class="small-note">New numeric fields are blank unless a labeled scoring or template assumption is provided. Blank is not evidence of zero.</p></section><section class="panel document-panel"><div id="tool-output" aria-live="polite"></div><div id="cross-actions" class="tool-controls no-print"></div></section></div>${id==='opportunities'?'<section class="panel ranking-panel"><h2>Saved process ranking</h2><div id="ranked-processes"></div></section>':''}`;
app.querySelectorAll('[data-field]').forEach(el=>el.oninput=()=>{values[el.dataset.field]=el.type==='number'?(el.value===''?'':Number(el.value)):el.value;clearTimeout(saveTimer);saveDraft();if(current.id==='audit'&&el.dataset.field==='type')auditMode();update();});document.querySelector('#new-reset').onclick=async()=>{if(await ask('Reset this draft to its empty template? Saved CRM records and ranked processes are retained.')){values=emptyValues(current);if(id==='crm')delete memory.links.crm;saveDraft(true);mountExtended(id)}};document.querySelector('#save-draft').onclick=async()=>{if(await ask(storageWarning?'Replace the unsupported saved tool data with this draft? Export a raw backup first.':'Save this draft in this browser?')){if(saveDraft(true))toast('Draft saved locally')}};
document.querySelector('#new-copy').onclick=async()=>{if(!result){toast('Correct validation errors first');return}copy(document.querySelector('#tool-output').innerText+(!['proposal','crm'].includes(current.id)?'\\n\\nInput evidence:\\n'+current.fields.filter(f=>values[f.key]!==''&&values[f.key]!==null).map(f=>f.label+': '+values[f.key]).join('\\n'):''))};
document.querySelector('#export-json').onclick=async()=>{if(id==='crm'){if(crmWarning){toast('Use the raw recovery backup first');return}download('ap-crm-backup.json',JSON.stringify({version:1,records:leads},null,2))}else{try{download(`ap-${id}.json`,JSON.stringify({version:1,tool:id,values:validateValues(current,values),...(id==='opportunities'?{processes:memory.processes}:{})},null,2))}catch(e){toast(e.message)}}};
document.querySelector('#import-json').onchange=importFile;
if(document.querySelector('#raw-backup'))document.querySelector('#raw-backup').onclick=async()=>download('ap-raw-recovery.json',JSON.stringify({extension:localStorage.getItem(NEW_KEY),crm:localStorage.getItem(CRM_KEY)},null,2));
if(document.querySelector('#print-report'))document.querySelector('#print-report').onclick=async()=>{if(!result){toast('Correct validation errors before printing');return}window.print()};
if(id==='proposal'){document.querySelector('#import-calc').onclick=async()=>{let c=calculators.find(c=>c.id===document.querySelector('#import-calculator').value);if(!c){toast('Choose a calculator');return}try{transfer('proposal',{assumptions:(values.assumptions?values.assumptions+'\n\n':'')+snapshotText(c,readOriginal(c.id))},'Imports saved inputs or fictional defaults when no scenario exists. Verify before presenting.')}catch(e){toast(e.message)}};document.querySelector('#apply-offer').onclick=async()=>{const launch=launchPackages.find(x=>x[0]===values.service);const patch=launch?{fee:launch[1],deliverables:'LLC formation process guidance\nEIN application guidance\nBusiness bank account preparation\nBusiness email setup\nInitial operational organization\nBasic business financial tracking\nInitial marketing guidance\nFirst-month support',exclusions:'Government charges and third-party fees are separate. Legal and tax advice are excluded. Exact scope requires review.',template:'Business Launch Concierge'}:{template:'ProfitOS Consulting',scope:values.service==='ProfitOS Monthly Optimization Retainer'?'Monthly review of agreed metrics and prioritized improvement experiments.':`Assess and address agreed business processes through ${values.service||'a defined ProfitOS engagement'}.`,deliverables:'Baseline findings and evidence review\nPrioritized action plan\nAgreed implementation or review deliverables',exclusions:'Results are estimates, not guarantees. Scope and pricing require client review.'};transfer('proposal',patch,'Preset fees and deliverables remain editable. ProfitOS fees are never invented.')}}
if(id==='crm'){document.querySelector('#save-lead').onclick=saveLead;document.querySelector('#csv-export').onclick=async()=>download('ap-crm.csv',csv(leads),'text/csv;charset=utf-8');document.querySelector('#clear-crm').onclick=async()=>{if(await ask('Permanently delete every local CRM record? Export a backup first. Calculator scenarios and tool drafts will remain.')){try{repo.clear();leads=[];crmWarning='';directory();toast('Local CRM records cleared')}catch{toast('Could not clear browser storage')}}};directory();}
else{document.querySelector('#lead-link').onchange=e=>{memory.links[id]=e.target.value;saveMemory()};document.querySelector('#use-lead').onclick=async()=>{const l=leads.find(l=>l.id===memory.links[id]);if(!l){toast('Select a local lead first');return}useLead(id,l)};if(id==='scoring')document.querySelector('#write-score').onclick=async()=>{const l=leads.find(l=>l.id===memory.links[id]);if(!l||result?.score===null||!result){toast('Select a lead and provide scoring evidence');return}if(await ask(`Replace ${l.business||l.contact} score ${l.score??'unknown'} with ${number(result.score)}? This is ${result.provisional?'provisional':'a qualification score'}, not a closing probability.`))commitLeads(leads.map(x=>x.id===l.id?{...x,score:Math.round(result.score)}:x))};}
if(id==='opportunities'){document.querySelector('#save-process').onclick=async()=>{try{const validated=validateValues(current,values);if(!validated.process.trim())throw Error('Enter a process name.');if(!result)throw Error('Correct evaluation errors first.');if(memory.processes.length>=100&&!processId)throw Error('Maximum 100 saved processes.');const item={id:processId??crypto.randomUUID(),values:validated};if(!await ask('Save this process to the local ranking'+(processId?' and replace its previous version?':'?')))return;memory.processes=processId?memory.processes.map(p=>p.id===processId?item:p):[...memory.processes,item];processId=item.id;if(saveMemory(true)){rankProcesses();toast('Process saved')}}catch(e){toast(e.message)}};rankProcesses()};if(id==='audit')auditMode();update();return true;}
function contextReport(){return `<details class="evidence-report"><summary>Complete input evidence & assumptions</summary>${current.fields.filter(f=>values[f.key]!==''&&values[f.key]!==null).map(f=>`<p><b>${esc(f.label)}:</b> ${para(values[f.key])}</p>`).join('')}</details>`}
function update(){const output=document.querySelector('#tool-output'),error=document.querySelector('#tool-error');error.textContent='';try{values=validateValues(current,values);const invalid=[...document.querySelectorAll('[data-field]')].some(el=>!el.checkValidity());if(invalid)throw Error('Correct the highlighted inputs.');switch(current.id){
case 'savings':{result=savings(values);const r=result;output.innerHTML=`<h2>Savings scenario</h2><p>${esc(values.basis)} · ${current.fields.some(f=>f.type==='number'&&values[f.key]==='')?'Provisional: blank amounts treated as zero.':'All numeric assumptions supplied.'}</p><div class="results result-box">${metric('Net monthly cash savings',money(r.net))}${metric('Annualized net savings',money(r.annual))}${metric('First-year net financial benefit',money(r.netAnnual))}${metric('Implementation cost',money(Number(values.implementation)||0))}${metric('Recurring software + maintenance / month',money(r.recurring))}${metric('Break-even period',r.payback===null?'Not attainable':number(r.payback)+' months')}${metric('First-year ROI',r.roi===null?'Undefined (no investment)':number(r.roi)+'%')}</div>${section('Separate capacity value',`${number(r.hours)} hours recovered monthly; ${money(r.capacity)} monthly capacity value. Not cash savings.`)}${section('Separate cost avoidance',money(r.avoidance)+' per month; excluded from cash savings and ROI.')}<h3>Cash realization sensitivity</h3><table><thead><tr><th>Gross reductions realized</th><th>Net / month</th><th>First-year net benefit</th></tr></thead><tbody>${r.sensitivity.map(s=>`<tr><td>${s.p}%</td><td>${money(s.net)}</td><td>${money(s.annual)}</td></tr>`).join('')}</tbody></table><p>Recurring costs remain constant in each scenario. Reductions must be non-overlapping and supported by evidence.</p>${section('Assumptions & evidence',values.evidence)}`;break}
case 'scoring':{result=leadScore(values);output.innerHTML=`<h2>${result.label}</h2>${scores(result)}${section('Strengths',result.breakdown.filter(b=>b.value>=70).map(b=>b.label).join(', '))}${section('Risks / lower ratings',result.breakdown.filter(b=>b.value!==null&&b.value<50).map(b=>b.label).join(', '))}${section('Missing qualification details',result.breakdown.filter(b=>b.value===null).map(b=>b.label).concat(['revenue','size','industry','budget','impact','evidence'].filter(k=>values[k]==='').map(k=>current.fields.find(f=>f.key===k).label)).join(', ')||'None in the listed fields.')}${section('Next sales action',result.next)}${section('Recommended service category',result.service)}<p>Heuristic qualification assessment. Not a statistically validated closing probability.</p>`;break}
case 'opportunities':{result=opportunity(values);const r=result;output.innerHTML=`<h2>${esc(values.process||'Process assessment')}</h2>${scores(r)}${section('Recommended priority',r.priority)}${section('Suggested approach',r.method)}${section('Implementation complexity',r.complexity)}${section('Potential operational benefits',`${number(r.hours)} hours potentially recovered per month; ${money(r.capacity)} capacity value per month. These are estimates, not guaranteed payroll or cash savings.`)}${section('Human review requirements',r.sensitive?'Specialist approval, access controls, and human review of every sensitive decision.':`Human oversight rating: ${number(n(values.oversight))}/100. Assign an accountable reviewer, test outputs, and require approval for consequential actions.`)}<h3>Major risks</h3>${list(r.risks)}${section('Implementation sequence','1. Map and simplify the process.\n2. Verify permission, data quality, and baseline time/error measurements.\n3. Pilot with non-sensitive samples and a named human reviewer.\n4. Compare measured outcomes and expand only after review.')}`;break}
case 'audit':{result=audit(values);const r=result;output.innerHTML=`<div class="report-cover"><div class="eyebrow">Aaron Pastrana Consulting</div><h2>${esc(values.type||'Business Audit')}</h2><h3>${esc(values.company||'Business name not supplied')}</h3><p>Preliminary consulting assessment · ${today()}</p></div>${section('Executive audit summary',`${values.company||'The business'} reports: ${values.challenges||'challenges not yet supplied'}. ${r.provisional?'Assessment is provisional because evidence is incomplete.':'All scoring inputs supplied; ratings remain subjective assessments.'} No operational results have been independently verified by this tool.`)}<h3>Areas of strength</h3>${list(r.strengths.map(s=>`${s.key}: ${number(s.score)}/100${s.provisional?' (provisional)':''}`))}<h3>Identified weaknesses</h3>${list(r.weaknesses.map(s=>`${s.key}: ${number(s.score)}/100${s.provisional?' (provisional)':''}`))}<h3>Ranked improvement opportunities</h3>${list(r.ranked.map((s,i)=>`${i+1}. ${s.key} — ${number(s.score)}/100. ${auditAction(s.key)}`))}<h3>Financial impact estimate</h3>${r.financial?`<div class="results result-box">${r.financial.map(([label,value,unit])=>metric(label,unit==='$'?money(value):number(value)+' '+(unit??''))).join('')}</div><p>Reuses Client Profit Improvement: leads × (target − current close rate) × transaction value × contribution margin + monthly cash savings. Annual assumes twelve identical months. No guaranteed results or independent verification.</p>`:'<p>Not calculated. Supply qualified leads, current and target closing rates, transaction value, contribution margin and monthly cash savings. Do not substitute revenue for profit.</p>'}${section('Recommended next steps',r.ranked.length?r.ranked.slice(0,3).map(s=>auditAction(s.key)).join('\n'):'Complete discovery evidence and ratings before recommending implementation.')}${section('Suggested ProfitOS engagement',r.engagement)}<h3>Transparent scoring</h3>${r.scores.map(s=>`<h4>${s.key==='ai'?'AI Readiness':({sales:'Sales Process Effectiveness',operations:'Operational Efficiency',financial:'Financial Visibility',growth:'Growth Readiness'}[s.key])}</h4>${scores(s)}`).join('')}`;break}
case 'proposal':{result={};const sections=[['Executive overview',values.overview],['Current business challenges',values.problems],['Proposed consulting engagement',[values.service,values.solutions].filter(Boolean).join('\n')],['Scope of work',values.scope],['Deliverables',values.deliverables],['Implementation timeline',[values.start?'Start: '+values.start:'Start date not supplied',values.timeline].filter(Boolean).join('\n')],['Expected benefits',values.benefits?values.benefits+'\nEstimates depend on the stated assumptions and are not guaranteed.':'No financial benefit estimate supplied.'],['Pricing and payment schedule',(n(values.fee)===null?'Consulting fee: not supplied':'Consulting fee: '+money(n(values.fee)))+'\n'+(values.milestones||'Payment milestones to be agreed.')+'\nGovernment charges and third-party fees are separate.'],['Client responsibilities',values.responsibilities],['Exclusions and assumptions',[values.exclusions,values.assumptions,'Process guidance only; no legal or tax advice. This proposal is for discussion and is not a legally approved or binding contract.'].filter(Boolean).join('\n')],['Next steps',values.next||'Review the scope, evidence, fee and schedule together before agreeing an engagement.']];output.innerHTML=`<article class="proposal-document"><div class="report-cover proposal-cover"><div class="eyebrow">Aaron Pastrana Consulting</div><h2>Consulting proposal</h2><h3>${esc(values.business||'Business name not supplied')}</h3><p>Prepared for ${esc(values.client||'Client name not supplied')}<br>${esc(values.industry)}<br>${esc(values.contact)}</p><p>${esc(values.service||values.template)}<br>${today()}</p><span class="gold">PREPARED FOR DISCUSSION</span></div>${sections.map(([h,t],i)=>section(`${i+2}. ${h}`,t)).join('')}</article>`;break}
case 'crm':{result={};output.innerHTML='<h2>Local prospect record</h2>'+section('Editing',editId?'Existing record — save changes explicitly.':'New unsaved lead. Nothing is added to the directory until Save lead.')+section('Privacy',privacy)+section('Record summary',[values.contact,values.business,values.stage,values.notes].filter(Boolean).join('\n'));break}
}if(current.id!=='proposal'&&current.id!=='crm')output.insertAdjacentHTML('beforeend',`<div class="formula">${esc(current.explanation)}</div>${contextReport()}`);crossActions();}catch(e){result=null;error.textContent=e.message;output.innerHTML='<h2>Review inputs</h2><p>'+esc(e.message)+'</p>';document.querySelector('#cross-actions').innerHTML='';}}
function auditAction(k){return {sales:'Document funnel stages, response standards and follow-up ownership.',operations:'Map the bottleneck and measure task time before changing workflows.',financial:'Reconcile expense categories and validate contribution margins.',ai:'Validate data safeguards, staff readiness and a supervised pilot.',growth:'Align delivery capacity with measured sales and margin performance.'}[k]}
function crossActions(){const host=document.querySelector('#cross-actions');host.innerHTML='';if(!result||current.id==='crm'||current.id==='proposal')return;const add=(label,fn)=>{const b=document.createElement('button');b.textContent=label;b.onclick=async()=>{try{await fn()}catch(e){toast(e.message)}};host.append(b)};
add('Create proposal from assessment',()=>{const p=memory.drafts.proposal??emptyValues(tools.find(t=>t.id==='proposal'));const text=document.querySelector('#tool-output').innerText;transfer('proposal',{business:values.company||values.business||p.business,problems:values.challenges||values.description||p.problems,assumptions:(p.assumptions?p.assumptions+'\n\n':'')+text},'This imports assessment evidence, not verified client achievements.',memory.links[current.id])});
if(current.id==='scoring')add('Use in mini business audit',()=>transfer('audit',{company:values.business,industry:values.industry,challenges:values.evidence,type:'Mini Business Audit'},'Only business context is transferred; scoring ratings have different meanings and are not copied.',memory.links.scoring));
if(current.id==='savings'){add('Use cash estimate in Client ROI',()=>transfer('roi',{f:Number(values.implementation)||0,s:0,o:0,c:0,v:result.net},'Replace investment and monthly benefit fields with this savings-only scenario. Existing ramp-up and evaluation periods remain. Capacity value and avoidance are excluded.'));add('Copy implementation cost to pricing',()=>transfer('pricing',{o:Number(values.implementation)||0},'Copy the one-time implementation expense as other project costs. Existing labor and software costs remain; check for overlap.'));}
if(current.id==='opportunities')add('Use time assumptions in Savings Estimator',()=>transfer('savings',{people:values.people,rate:values.rate,hours:(Number(values.frequency)||0)*(Number(values.minutes)||0)/60,reduced:(Number(values.frequency)||0)*(Number(values.minutes)||0)/60*(Number(values.recovery)||0)/100,frequency:values.frequency,basis:'Assumed — unverified scenario',evidence:values.process+'\n'+values.evidence+'\nTime recovery is a capacity assumption; do not count it as payroll cash savings without evidence.'},'No cash savings are inferred from time recovery. Existing expense assumptions remain and require review.',memory.links.opportunities));
if(current.id==='audit'){add('Open savings scenario from audit',()=>transfer('savings',{subscriptions:values.subscriptions,evidence:'Audit of '+values.company+'\n'+values.unnecessary+'\n'+values.bottlenecks+'\nReported total cost reduction: '+(values.cashSavings||'unknown')+' USD/month. Allocate reductions to disjoint cost buckets before calculating.'},'Copies context only; reported total reductions are not silently assigned to a savings category.',memory.links.audit));if(result.financial)add('Use financial estimate in Client ROI',()=>transfer('roi',{c:result.financial[2][1],v:Number(values.cashSavings)},'Copies incremental contribution and cash savings only. Existing investment, ramp-up, and evaluation assumptions remain.'));}}
function commitLeads(next){if(crmWarning){toast('Invalid saved CRM data needs recovery. Import a validated replacement or explicitly clear CRM first.');return false}try{leads=repo.save(next);toast('Local CRM saved');if(current?.id==='crm')directory();return true}catch(e){toast('Not saved: '+e.message);return false}}
function saveLead(){try{if(!document.querySelector('.editor').querySelectorAll('[data-field]'))return;const v=validateValues(current,values);const next={...v,id:editId??crypto.randomUUID(),archived:editId?leads.find(r=>r.id===editId)?.archived??false:false};if(!next.added)next.added=today();if(!editId&&leads.length>=1000)throw Error('Maximum 1,000 leads.');if(commitLeads(editId?leads.map(l=>l.id===editId?next:l):[...leads,next])){editId=next.id;memory.links.crm=editId;saveDraft();update()}}catch(e){toast(e.message)}}
function directory(){const stats=crmStats(leads,today());const host=document.querySelector('#crm-directory');host.innerHTML=`<h2>Local lead directory</h2><div class="crm-stats">${[['Total leads',stats.total],['Active opportunities',stats.active],['Upcoming follow-ups',stats.upcoming],['Overdue follow-ups',stats.overdue],['Proposals pending',stats.proposals],['Won customers',stats.won],['Open pipeline value',money(stats.pipeline)]].map(([k,v])=>`<div><strong>${esc(v)}</strong><span>${k}</span></div>`).join('')}</div><div class="tool-controls"><label>Search leads<input id="crm-search" type="search" value="${esc(search)}" placeholder="Name, business, email, notes"></label><label>Filter stage<select id="crm-stage"><option value="">All stages</option>${tools.find(t=>t.id==='crm').fields.find(f=>f.key==='stage').options.map(s=>`<option ${stageFilter===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Archive filter<select id="crm-archive"><option value="active">Active records</option><option value="archived" ${archived?'selected':''}>Archived records</option></select></label></div><div id="crm-list"></div>`;document.querySelector('#crm-search').oninput=e=>{search=e.target.value;leadList()};document.querySelector('#crm-stage').onchange=e=>{stageFilter=e.target.value;leadList()};document.querySelector('#crm-archive').onchange=e=>{archived=e.target.value==='archived';leadList()};leadList()}
function leadList(){const filtered=leads.filter(l=>l.archived===archived&&(!stageFilter||l.stage===stageFilter)&&[l.contact,l.business,l.email,l.notes,l.industry].join(' ').toLowerCase().includes(search.toLowerCase()));const host=document.querySelector('#crm-list');host.innerHTML=filtered.length?filtered.map(l=>`<article class="lead-card"><div><h3>${esc(l.business||l.contact)}</h3><p>${esc(l.contact)} · ${esc(l.stage)} · ${l.value===null?'Value unknown':money(l.value)}<br>Follow-up: ${esc(l.followup||'not set')}${l.followup&&l.followup<today()&&!['Won','Lost'].includes(l.stage)?' · OVERDUE':''}</p></div><div class="tool-controls"><button data-edit="${esc(l.id)}">Edit</button><button data-archive="${esc(l.id)}">${l.archived?'Restore':'Archive'}</button>${['scoring','audit','savings','proposal'].map(id=>`<button data-use="${id}" data-lead="${esc(l.id)}">${tools.find(t=>t.id===id).name}</button>`).join('')}</div></article>`).join(''):'<p>No matching leads. Add a non-sensitive test lead below.</p>';host.querySelectorAll('[data-edit]').forEach(b=>b.onclick=async()=>{const l=leads.find(l=>l.id===b.dataset.edit);editId=l.id;memory.links.crm=editId;values=validateValues(current,l);document.querySelectorAll('[data-field]').forEach(el=>el.value=values[el.dataset.field]??'');saveDraft();update();document.querySelector('.editor').scrollIntoView({behavior:'smooth'})});host.querySelectorAll('[data-archive]').forEach(b=>b.onclick=async()=>{const l=leads.find(l=>l.id===b.dataset.archive);if(await ask(`${l.archived?'Restore':'Archive'} ${l.business||l.contact}?`))commitLeads(leads.map(r=>r.id===l.id?{...r,archived:!r.archived}:r))});host.querySelectorAll('[data-use]').forEach(b=>b.onclick=async()=>useLead(b.dataset.use,leads.find(l=>l.id===b.dataset.lead)))}
function useLead(id,l){const patch=id==='proposal'?{client:l.contact,business:l.business,industry:l.industry,contact:[l.email,l.phone].filter(Boolean).join(' · '),...(tools.find(t=>t.id==='proposal').fields.find(f=>f.key==='service').options.includes(l.service)?{service:l.service}:{}),...(l.value!==null?{fee:l.value}:{}),problems:l.notes}:id==='scoring'?{business:l.business,industry:l.industry,evidence:l.notes}:id==='audit'?{company:l.business,industry:l.industry,challenges:l.notes}:{evidence:'Lead: '+(l.business||l.contact)+'\n'+l.notes};transfer(id,patch,'This copies local lead context only and does not update the CRM record.',l.id)}
async function importFile(e){const input=e.target,file=input.files?.[0];if(!file)return;try{if(file.size>2000000)throw Error('Import limit is 2 MB.');const raw=await file.text();if(current.id==='crm'){const incoming=parseCRM(raw);const merge=await ask(`Validated ${incoming.length} lead records. Confirm: merge without overwriting existing IDs. Cancel: choose replacement in the next confirmation.`);let next;if(merge)next=mergeLeads(leads,incoming);else{if(!await ask(`Replace ALL ${leads.length} existing local leads with these ${incoming.length} validated records? Export a backup first.`))return;next=incoming}leads=repo.save(next);crmWarning='';directory();toast('Validated CRM import saved')}else{const imported=validateValues(current,parseDraft(raw,current.id));const parsed=JSON.parse(raw);const processes=current.id==='opportunities'&&parsed.processes!==undefined?validateProcesses(parsed.processes):null;if(!await ask('Replace this tool draft'+(processes?' and its saved process ranking':'')+' with the validated import? Other tool data will remain.'))return;memory.drafts[current.id]=imported;if(processes)memory.processes=processes;if(saveMemory(true))mountExtended(current.id)}}catch(e){toast('Import rejected: '+e.message)}finally{input.value=''}}
function rankProcesses(){const host=document.querySelector('#ranked-processes');const ranked=memory.processes.map(p=>({...p,result:opportunity(p.values)})).sort((a,b)=>Number(a.result.sensitive)-Number(b.result.sensitive)||(b.result.score??-1)-(a.result.score??-1)||b.result.capacity-a.result.capacity);host.innerHTML='<p>Ranked by safety gate, then suitability score, then estimated capacity value. Provisional scores require more evidence. Capacity value is not cash savings.</p>'+(ranked.length?ranked.map(p=>`<article class="lead-card"><h3>${esc(p.values.process)}</h3><p>${number(p.result.score)}/100${p.result.provisional?' (provisional)':''} · ${money(p.result.capacity)}/month capacity value · ${esc(p.result.priority)}</p><button data-process="${esc(p.id)}">Edit assessment</button> <button data-delete-process="${esc(p.id)}">Remove</button></article>`).join(''):'<p>No saved process assessments.</p>');host.querySelectorAll('[data-process]').forEach(b=>b.onclick=async()=>{const p=memory.processes.find(p=>p.id===b.dataset.process);processId=p.id;values={...p.values};document.querySelectorAll('[data-field]').forEach(el=>el.value=values[el.dataset.field]??'');saveDraft();update();document.querySelector('.editor').scrollIntoView()});host.querySelectorAll('[data-delete-process]').forEach(b=>b.onclick=async()=>{if(await ask('Remove this saved process from the ranking?')){memory.processes=memory.processes.filter(p=>p.id!==b.dataset.deleteProcess);if(processId===b.dataset.deleteProcess)processId=null;if(saveMemory(true))rankProcesses()}})}
export function clearNewData(){clearTimeout(saveTimer);localStorage.removeItem(NEW_KEY);localStorage.removeItem(CRM_KEY);memory={version:1,drafts:{},processes:[],links:{}};leads=[];storageWarning='';crmWarning='';editId=null;processId=null;}
let printDetails=[];window.addEventListener('beforeprint',()=>{printDetails=[...document.querySelectorAll('#tool-output details')].map(el=>({el,open:el.open}));printDetails.forEach(({el})=>el.open=true)});window.addEventListener('afterprint',()=>{printDetails.forEach(({el,open})=>el.open=open);printDetails=[]});

function auditMode(){const comprehensive=values.type==='Comprehensive Business Audit';document.querySelectorAll('.form-group').forEach(d=>{const title=d.querySelector('summary').textContent;d.open=comprehensive||['Audit','Business information','Sales performance','Assessment ratings','Impact assumptions'].includes(title)})}
